function renderRiskDashboardHtml(_env, url) {
  const { envLabel, envColor, workerOrigin } = envLabelAndColor(url);
  return dashboardShell({
    title: "\u{1F3AF} Risk Dashboard",
    envLabel,
    envColor,
    workerOrigin,
    activeNav: "/tos/dashboard/risk",
    body: `
      <div style="margin-bottom:14px;color:#94a3b8;font-size:13px;">Open transactions grouped by risk band. RED deals are listed first with their top contributing factors. Run Risk Sweep from the Admin page to recompute.</div>
      <div id="risk-summary" style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:24px;"></div>
      <div id="risk-content"><div class="empty">Loading transactions\u2026</div></div>
    `,
    bodyScript: `
      async function loadData() {
        try {
          const r = await fetch(WORKER_ORIGIN + '/tos/admin/transactions', { cache: 'no-store' });
          const data = await r.json();
          if (!data.ok) throw new Error(data.error || 'fetch failed');
          const open = data.transactions.filter(function(t) { return !t.terminal; });
          const byBand = { RED: [], YELLOW: [], GREEN: [], unscored: [] };
          open.forEach(function(t) { (byBand[t.riskBand] || byBand.unscored).push(t); });

          var summary = '';
          [['RED','#ef4444'], ['YELLOW','#f59e0b'], ['GREEN','#22c55e'], ['unscored','#94a3b8']].forEach(function(pair) {
            var label = pair[0], color = pair[1];
            summary += '<div style="padding:18px;background:#1e293b;border:1px solid #334155;border-radius:10px;">'
              + '<div style="font-size:11px;color:#94a3b8;text-transform:uppercase;letter-spacing:0.05em;font-weight:600;margin-bottom:8px;">' + label + '</div>'
              + '<div style="font-size:32px;font-weight:700;color:' + color + ';line-height:1.1">' + byBand[label].length + '</div>'
              + '</div>';
          });
          document.getElementById('risk-summary').innerHTML = summary;

          var html = '';
          ['RED', 'YELLOW', 'GREEN', 'unscored'].forEach(function(band) {
            var rows = byBand[band];
            if (rows.length === 0) return;
            var bandClass = band === 'RED' ? 'pill-red' : band === 'YELLOW' ? 'pill-yellow' : band === 'GREEN' ? 'pill-green' : 'pill-gray';
            html += '<div style="margin-bottom:24px;"><div style="margin-bottom:8px;font-size:13px;font-weight:600;color:#cbd5e1;"><span class="pill ' + bandClass + '">' + band + '</span> \xB7 ' + rows.length + ' transaction' + (rows.length===1?'':'s') + '</div>';
            html += '<table><thead><tr><th>Transaction</th><th>Score</th><th>Stage</th><th>Closing</th><th>Top Factors</th></tr></thead><tbody>';
            for (var i = 0; i < rows.length; i++) {
              var t = rows[i];
              html += '<tr style="cursor:pointer;" onclick="location.href=\\'/tos/dashboard/deal?id=' + t.id + '\\'" title="Click to open deal detail">'
                + '<td>' + escapeHtml(t.name) + '<div class="mono">' + t.id.slice(0,12) + '\u2026 <span style="color:#22d3ee;">\u2197</span></div></td>'
                + '<td>' + (t.riskScore !== null ? t.riskScore : '\u2014') + '</td>'
                + '<td>' + escapeHtml(t.stage) + '</td>'
                + '<td>' + fmtDate(t.closingDate) + '</td>'
                + '<td style="font-size:12px;color:#94a3b8;">' + escapeHtml(t.riskTopFactors || '\u2014') + '</td>'
                + '</tr>';
            }
            html += '</tbody></table></div>';
          });
          if (!html) html = '<div class="empty">No open transactions yet.</div>';
          document.getElementById('risk-content').innerHTML = html;
        } catch (e) {
          document.getElementById('risk-content').innerHTML = '<div class="empty" style="color:#ef4444;">Error: ' + escapeHtml(e.message || e) + '</div>';
        }
      }
    `
  });
}
__name(renderRiskDashboardHtml, "renderRiskDashboardHtml");
function renderDeadlinesDashboardHtml(_env, url) {
  const { envLabel, envColor, workerOrigin } = envLabelAndColor(url);
  return dashboardShell({
    title: "\u23F0 Deadlines",
    envLabel,
    envColor,
    workerOrigin,
    activeNav: "/tos/dashboard/deadlines",
    body: `
      <div style="margin-bottom:14px;color:#94a3b8;font-size:13px;">All deadlines across open transactions, grouped by status. Overdue first, then Due Soon, then Upcoming. Run Deadline Sweep from the Admin page to refresh statuses.</div>
      <div id="deadlines-summary" style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:24px;"></div>
      <div id="deadlines-content"><div class="empty">Loading deadlines\u2026</div></div>
    `,
    bodyScript: `
      async function loadData() {
        try {
          const r = await fetch(WORKER_ORIGIN + '/tos/admin/deadlines', { cache: 'no-store' });
          const data = await r.json();
          if (!data.ok) throw new Error(data.error || 'fetch failed');
          const all = data.deadlines;
          const overdue = all.filter(function(d) { return d.daysUntil !== null && d.daysUntil < 0; });
          const dueSoon = all.filter(function(d) { return d.daysUntil !== null && d.daysUntil >= 0 && d.daysUntil <= 7; });
          const upcoming = all.filter(function(d) { return d.daysUntil !== null && d.daysUntil > 7; });
          const noDate = all.filter(function(d) { return d.daysUntil === null; });
          overdue.sort(function(a,b) { return a.daysUntil - b.daysUntil; });
          dueSoon.sort(function(a,b) { return a.daysUntil - b.daysUntil; });
          upcoming.sort(function(a,b) { return a.daysUntil - b.daysUntil; });

          var summary = '';
          [['Overdue', overdue.length, '#ef4444'], ['Due Soon (7d)', dueSoon.length, '#f59e0b'], ['Upcoming', upcoming.length, '#22c55e'], ['No Date', noDate.length, '#94a3b8']].forEach(function(t) {
            summary += '<div style="padding:18px;background:#1e293b;border:1px solid #334155;border-radius:10px;">'
              + '<div style="font-size:11px;color:#94a3b8;text-transform:uppercase;letter-spacing:0.05em;font-weight:600;margin-bottom:8px;">' + t[0] + '</div>'
              + '<div style="font-size:32px;font-weight:700;color:' + t[2] + ';line-height:1.1">' + t[1] + '</div></div>';
          });
          document.getElementById('deadlines-summary').innerHTML = summary;

          function renderSection(title, rows, cls) {
            if (rows.length === 0) return '';
            var h = '<div style="margin-bottom:24px;"><div style="margin-bottom:8px;font-size:13px;font-weight:600;color:#cbd5e1;">' + title + ' \xB7 ' + rows.length + '</div>';
            h += '<table><thead><tr><th>Days</th><th>Type</th><th>Status</th><th>Due Date</th><th>Transaction</th></tr></thead><tbody>';
            for (var i = 0; i < rows.length; i++) {
              var d = rows[i];
              var dayLabel = d.daysUntil === null ? '\u2014' : d.daysUntil < 0 ? Math.abs(d.daysUntil) + 'd ago' : d.daysUntil === 0 ? 'TODAY' : d.daysUntil + 'd';
              var clickAttr = d.parentTransactionId ? ' style="cursor:pointer;" onclick="location.href=\\'/tos/dashboard/deal?id=' + d.parentTransactionId + '\\'"' : '';
              var parentLabel = d.parentTransactionId
                ? '<span style="color:#22d3ee;">\u{1F4C2} ' + escapeHtml((d.parentTransactionName || d.parentTransactionId).slice(0,40)) + ' \u2197</span>'
                : '<span style="color:#64748b;">orphan</span>';
              h += '<tr' + clickAttr + ' title="' + (d.parentTransactionId ? 'Click to open deal detail' : 'No parent transaction linked') + '">'
                + '<td><span class="pill ' + cls + '">' + dayLabel + '</span></td>'
                + '<td>' + escapeHtml(d.type) + '</td>'
                + '<td>' + escapeHtml(d.status) + '</td>'
                + '<td>' + fmtDate(d.dueDate) + '</td>'
                + '<td>' + parentLabel + '</td>'
                + '</tr>';
            }
            h += '</tbody></table></div>';
            return h;
          }

          var html = renderSection('\u{1F534} Overdue', overdue, 'pill-red')
            + renderSection('\u{1F7E1} Due Soon', dueSoon, 'pill-yellow')
            + renderSection('\u{1F7E2} Upcoming', upcoming, 'pill-green')
            + renderSection('\u26AA No Due Date', noDate, 'pill-gray');
          if (!html) html = '<div class="empty">No deadlines yet. They get created when contracts are parsed.</div>';
          document.getElementById('deadlines-content').innerHTML = html;
        } catch (e) {
          document.getElementById('deadlines-content').innerHTML = '<div class="empty" style="color:#ef4444;">Error: ' + escapeHtml(e.message || e) + '</div>';
        }
      }
    `
  });
}
