function renderCommandDashboardHtml(_env, url) {
  const { envLabel, envColor, workerOrigin } = envLabelAndColor(url);
  return dashboardShell({
    title: "\u{1F39B}\uFE0F Command Center",
    envLabel,
    envColor,
    workerOrigin,
    activeNav: "/tos/dashboard/command",
    body: `
      <div style="margin-bottom:18px;color:#94a3b8;font-size:13px;">Single-pane view of what needs your attention right now. Built for the person running the system end-to-end.</div>

      <!-- WELCOME BANNER (first visit only, dismissible) -->
      <div id="welcome-banner" style="display:none;margin-bottom:20px;padding:18px 22px;background:linear-gradient(135deg,#1e3a5f,#0c4a6e);border:1px solid #22d3ee;border-radius:12px;box-shadow:0 4px 20px rgba(34,211,238,0.15);">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:14px;">
          <div style="flex:1;">
            <div style="font-size:11px;color:#7dd3fc;text-transform:uppercase;letter-spacing:0.08em;font-weight:700;margin-bottom:6px;">\u{1F44B} Welcome to your Command Center</div>
            <div style="font-size:15px;color:#e2e8f0;font-weight:600;margin-bottom:8px;">First time here? Three things to know:</div>
            <ul style="color:#cbd5e1;font-size:13px;line-height:1.7;margin:0;padding-left:20px;">
              <li>Red tiles above = needs action right now. Click any tile to drill in.</li>
              <li>"What needs your attention" below = your prioritized to-do list (RED \u2192 YELLOW \u2192 INFO).</li>
              <li>If everything is green and the list is empty, close the tab \u2014 you're done. The system handles the rest.</li>
            </ul>
            <div style="margin-top:10px;font-size:12px;">
              <a href="/tos/dashboard/help" style="color:#7dd3fc;font-weight:600;">\u{1F4D6} Full setup guide \u2192</a>
              <span style="margin:0 8px;color:#475569;">\xB7</span>
              <a href="/tos/dashboard/deals" style="color:#7dd3fc;">\u{1F0CF} Browse all deals \u2192</a>
              <span style="margin:0 8px;color:#475569;">\xB7</span>
              <a href="#" onclick="seedDemoData(event)" style="color:#7dd3fc;">\u{1F331} Seed demo data \u2192</a>
            </div>
          </div>
          <button onclick="dismissWelcome()" style="padding:6px 12px;background:transparent;border:1px solid #334155;color:#94a3b8;border-radius:6px;cursor:pointer;font-size:11px;">Got it \u2715</button>
        </div>
      </div>

      <!-- HERO: 4 big attention tiles -->
      <div id="hero-tiles" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin-bottom:24px;"></div>

      <!-- PIPELINE FUNNEL: deals by stage -->
      <div class="stat-tile" style="margin-bottom:20px;">
        <div class="stat-label" style="margin-bottom:14px;display:flex;justify-content:space-between;align-items:center;">
          <span>\u{1F4CA} Pipeline funnel \u2014 deals at each stage</span>
          <span id="funnel-total" style="color:#cbd5e1;font-size:12px;font-weight:normal;text-transform:none;letter-spacing:0;"></span>
        </div>
        <div id="funnel"></div>
      </div>

      <!-- TWO-COLUMN: Action queue + Quick actions -->
      <div style="display:grid;grid-template-columns:1fr 320px;gap:16px;margin-bottom:20px;">

        <!-- ACTION QUEUE: things needing operator attention -->
        <div class="stat-tile">
          <div class="stat-label" style="margin-bottom:12px;">\u26A0\uFE0F What needs your attention</div>
          <div id="attention-list"></div>
        </div>

        <!-- QUICK ACTIONS -->
        <div class="stat-tile">
          <div class="stat-label" style="margin-bottom:12px;">\u26A1 Quick actions</div>
          <div style="display:flex;flex-direction:column;gap:8px;">
            <a href="/tos/dashboard/closings" class="cmd-quick">\u{1F4C5} Open Calendar</a>
            <a href="/tos/dashboard/deals" class="cmd-quick">\u{1F0CF} Browse Deals</a>
            <a href="/tos/dashboard/risk" class="cmd-quick">\u{1F3AF} Risk Drill-down</a>
            <a href="/tos/dashboard/deadlines" class="cmd-quick">\u23F0 Deadlines List</a>
            <a href="/tos/admin" class="cmd-quick" style="border-color:#22d3ee;color:#22d3ee;">\u{1F6E0}\uFE0F Admin Console</a>
            <button onclick="runCmd('/tos/risk/sweep')" class="cmd-quick" data-needs-auth>\u{1F3AF} Run Risk Sweep</button>
            <button onclick="runCmd('/tos/deadlines/sweep')" class="cmd-quick" data-needs-auth>\u23F0 Run Deadline Sweep</button>
          </div>
          <div style="margin-top:14px;padding-top:12px;border-top:1px solid #334155;">
            <div style="font-size:11px;color:#94a3b8;margin-bottom:6px;">Action buttons require operator password:</div>
            <div style="display:flex;gap:6px;align-items:center;">
              <input type="password" id="cmd-key" placeholder="Operator password" style="flex:1;padding:5px 8px;background:#0f172a;border:1px solid #334155;border-radius:4px;color:#e2e8f0;font-family:monospace;font-size:11px;" />
              <button id="cmd-unlock" class="cmd-quick" style="padding:5px 10px;font-size:11px;">Unlock</button>
            </div>
            <div id="cmd-auth-status" style="font-size:10px;color:#64748b;margin-top:4px;">\u{1F512} locked</div>
          </div>
        </div>

      </div>

      <!-- TOP 5 AT-RISK DEALS -->
      <div class="stat-tile" style="margin-bottom:20px;">
        <div class="stat-label" style="margin-bottom:12px;display:flex;justify-content:space-between;align-items:center;">
          <span>\u{1F525} Top 5 deals at risk</span>
          <span style="color:#cbd5e1;font-size:11px;text-transform:none;letter-spacing:0;font-weight:normal;">RED band, sorted by closing date proximity</span>
        </div>
        <div id="cmd-top-risk"></div>
      </div>

      <!-- ACTIVITY FEED -->
      <div class="stat-tile">
        <div class="stat-label" style="margin-bottom:12px;">\u{1F4DC} Recent worker activity</div>
        <div id="cmd-activity"></div>
      </div>

      <style>
        .hero-tile { padding: 22px 20px; background: #1e293b; border: 1px solid #334155; border-radius: 12px; text-align: center; transition: transform 0.15s, border-color 0.15s; cursor: pointer; }
        .hero-tile:hover { transform: translateY(-2px); border-color: #22d3ee; }
        .hero-tile .icon { font-size: 28px; line-height: 1; margin-bottom: 8px; }
        .hero-tile .num { font-size: 42px; font-weight: 800; line-height: 1; margin-bottom: 6px; }
        .hero-tile .label { font-size: 11px; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.06em; font-weight: 600; }
        .hero-tile.red { border-color: #ef4444; }
        .hero-tile.red .num { color: #ef4444; }
        .hero-tile.yellow { border-color: #f59e0b; }
        .hero-tile.yellow .num { color: #f59e0b; }
        .hero-tile.green .num { color: #22c55e; }
        .hero-tile.cyan .num { color: #22d3ee; }
        .hero-tile.gray .num { color: #64748b; }
        .funnel-row { display: flex; align-items: center; gap: 10px; margin-bottom: 6px; font-size: 13px; }
        .funnel-stage { width: 200px; color: #cbd5e1; }
        .funnel-bar-wrap { flex: 1; height: 24px; background: #0f172a; border-radius: 4px; overflow: hidden; position: relative; }
        .funnel-bar { height: 100%; background: linear-gradient(90deg, #22d3ee, #0891b2); transition: width 0.5s; }
        .funnel-count { width: 60px; text-align: right; color: #cbd5e1; font-weight: 600; }
        .attn-item { padding: 10px 12px; background: #0f172a; border-left: 3px solid #ef4444; border-radius: 4px; margin-bottom: 8px; font-size: 13px; color: #cbd5e1; display: flex; gap: 10px; align-items: flex-start; }
        .attn-item.yellow { border-color: #f59e0b; }
        .attn-item.info { border-color: #22d3ee; }
        .attn-item .icon { font-size: 16px; line-height: 1; flex-shrink: 0; }
        .cmd-quick { padding: 10px 14px; background: #1a2236; border: 1px solid #334155; color: #cbd5e1; border-radius: 6px; text-decoration: none; cursor: pointer; font-size: 13px; text-align: left; transition: border-color 0.15s, color 0.15s; }
        .cmd-quick:hover { border-color: #22d3ee; color: #22d3ee; }
        .cmd-quick:disabled { opacity: 0.5; cursor: not-allowed; }
        .act-row { padding: 8px 0; border-bottom: 1px solid #2a3a52; font-size: 12px; color: #cbd5e1; }
        .act-row:last-child { border-bottom: none; }
        body[data-theme="light"] .hero-tile { background: #ffffff !important; }
        body[data-theme="light"] .funnel-bar-wrap { background: #e2e8f0 !important; }
        body[data-theme="light"] .attn-item { background: #f8fafc !important; }
      </style>
    `,
    bodyScript: `
      var cmd_data = { transactions: [], deadlines: [], stats: null };
      var cmd_apiKey = localStorage.getItem('tos_admin_key') || '';

      function updateCmdAuth() {
        var unlocked = !!cmd_apiKey;
        document.getElementById('cmd-auth-status').innerHTML = unlocked ? '<span style="color:#22c55e">\u{1F513} unlocked</span>' : '<span style="color:#64748b">\u{1F512} locked</span>';
        document.getElementById('cmd-key').style.display = unlocked ? 'none' : 'inline-block';
        document.getElementById('cmd-unlock').style.display = unlocked ? 'none' : 'inline-block';
        Array.from(document.querySelectorAll('button[data-needs-auth]')).forEach(function(b){ b.disabled = !unlocked; });
      }
      document.getElementById('cmd-unlock').addEventListener('click', function() {
        var k = document.getElementById('cmd-key').value.trim();
        if (!k) { alert('Enter operator password first'); return; }
        cmd_apiKey = k; localStorage.setItem('tos_admin_key', k); updateCmdAuth();
      });

      async function runCmd(path) {
        if (!cmd_apiKey) { alert('Unlock first'); return; }
        var r = await fetch(WORKER_ORIGIN + path, {
          method: 'POST', headers: { 'Authorization': 'Bearer ' + cmd_apiKey, 'Content-Type': 'application/json' }, body: '{}',
        });
        var b = await r.json();
        alert(path + '\\n\\nHTTP ' + r.status + '\\n\\n' + JSON.stringify(b, null, 2).slice(0, 800));
        loadData();
      }
      window.runCmd = runCmd;

      function renderHero() {
        var today = new Date(); today.setHours(0,0,0,0);
        var open = cmd_data.transactions.filter(function(t){ return !t.terminal; });
        var redCount = open.filter(function(t){ return t.riskBand === 'RED'; }).length;
        var closingsToday = open.filter(function(t){
          if (!t.closingDate) return false;
          var d = new Date(t.closingDate); d.setHours(0,0,0,0);
          return d.getTime() === today.getTime();
        }).length;
        var closingsThisWeek = open.filter(function(t){
          if (!t.closingDate) return false;
          var d = new Date(t.closingDate); d.setHours(0,0,0,0);
          var days = (d.getTime() - today.getTime()) / 86400000;
          return days >= 0 && days <= 7;
        }).length;
        var overdueDeadlines = (cmd_data.deadlines || []).filter(function(d){ return d.daysUntil != null && d.daysUntil < 0; }).length;

        function tile(cls, icon, num, label, href) {
          return '<a href="' + href + '" class="hero-tile ' + cls + '" style="text-decoration:none;color:inherit;display:block;">' +
            '<div class="icon">' + icon + '</div>' +
            '<div class="num">' + num + '</div>' +
            '<div class="label">' + label + '</div>' +
          '</a>';
        }

        document.getElementById('hero-tiles').innerHTML =
          tile(redCount > 0 ? 'red' : 'gray',  '\u{1F534}', redCount, redCount === 1 ? 'RED Deal' : 'RED Deals', '/tos/dashboard/risk') +
          tile(overdueDeadlines > 0 ? 'red' : 'gray', '\u23F0', overdueDeadlines, 'Overdue', '/tos/dashboard/deadlines') +
          tile(closingsToday > 0 ? 'yellow' : 'gray', '\u{1F3E0}', closingsToday, 'Closing Today', '/tos/dashboard/closings') +
          tile(closingsThisWeek > 0 ? 'cyan' : 'gray', '\u{1F4C5}', closingsThisWeek, 'Closing 7 Days', '/tos/dashboard/closings');
      }

      function renderFunnel() {
        var open = cmd_data.transactions.filter(function(t){ return !t.terminal; });
        document.getElementById('funnel-total').textContent = open.length + ' open ' + (open.length === 1 ? 'deal' : 'deals');
        var byStage = {};
        open.forEach(function(t){ byStage[t.stage] = (byStage[t.stage] || 0) + 1; });
        var stages = Object.keys(byStage).sort(function(a,b){ return byStage[b] - byStage[a]; });
        if (stages.length === 0) {
          document.getElementById('funnel').innerHTML = '<div style="color:#64748b;font-size:12px;padding:14px 0;">No open deals to chart.</div>';
          return;
        }
        var max = Math.max.apply(null, stages.map(function(s){ return byStage[s]; }));
        document.getElementById('funnel').innerHTML = stages.map(function(s){
          var pct = Math.round((byStage[s] / max) * 100);
          return '<div class="funnel-row">' +
            '<div class="funnel-stage">' + escapeHtml(s) + '</div>' +
            '<div class="funnel-bar-wrap"><div class="funnel-bar" style="width:' + pct + '%;"></div></div>' +
            '<div class="funnel-count">' + byStage[s] + '</div>' +
          '</div>';
        }).join('');
      }

      function renderAttention() {
        var today = new Date(); today.setHours(0,0,0,0);
        var open = cmd_data.transactions.filter(function(t){ return !t.terminal; });
        var items = [];

        open.filter(function(t){ return t.riskBand === 'RED'; }).forEach(function(t){
          items.push({ level: 'red', icon: '\u{1F534}', text: t.name + ' is RED \u2014 top factors: ' + (t.riskTopFactors || 'recompute risk to see') });
        });
        (cmd_data.deadlines || []).filter(function(d){ return d.daysUntil != null && d.daysUntil < 0; }).forEach(function(d){
          items.push({ level: 'red', icon: '\u23F0', text: d.type + ' deadline was ' + Math.abs(d.daysUntil) + ' days ago (status: ' + d.status + ')' });
        });
        open.forEach(function(t){
          if (!t.closingDate) return;
          var due = new Date(t.closingDate); due.setHours(0,0,0,0);
          var days = (due.getTime() - today.getTime()) / 86400000;
          if (days === 0) items.push({ level: 'red', icon: '\u{1F3E0}', text: t.name + ' is closing TODAY' });
          else if (days > 0 && days <= 3) items.push({ level: 'yellow', icon: '\u{1F3E0}', text: t.name + ' closes in ' + days + ' day' + (days === 1 ? '' : 's') });
        });
        open.filter(function(t){ return !t.closingDate && t.stage === 'Contract Intake'; }).forEach(function(t){
          items.push({ level: 'info', icon: '\u{1F4C4}', text: t.name + ' has no closing date \u2014 contract may not be parsed' });
        });
        open.filter(function(t){ return t.riskScore == null && t.stage !== 'Contract Intake'; }).forEach(function(t){
          items.push({ level: 'info', icon: '\u{1F3AF}', text: t.name + ' is unscored \u2014 needs risk recompute' });
        });

        if (items.length === 0) {
          document.getElementById('attention-list').innerHTML =
            '<div style="padding:16px;text-align:center;color:#22c55e;font-size:13px;background:rgba(34,197,94,0.06);border-left:3px solid #22c55e;border-radius:4px;">\u2713 All clear \u2014 nothing needs immediate attention.</div>';
          return;
        }
        var levelOrder = { red: 0, yellow: 1, info: 2 };
        items.sort(function(a,b){ return levelOrder[a.level] - levelOrder[b.level]; });
        document.getElementById('attention-list').innerHTML = items.slice(0, 12).map(function(i){
          return '<div class="attn-item ' + i.level + '"><span class="icon">' + i.icon + '</span><span>' + escapeHtml(i.text) + '</span></div>';
        }).join('') + (items.length > 12 ? '<div style="font-size:11px;color:#64748b;text-align:center;padding-top:6px;">+' + (items.length - 12) + ' more \u2014 see Risk and Deadlines dashboards</div>' : '');
      }

      function renderActivity() {
        var acts = (cmd_data.stats && cmd_data.stats.recentActivity) || [];
        if (acts.length === 0) {
          document.getElementById('cmd-activity').innerHTML = '<div style="font-size:12px;color:#64748b;">No recent activity.</div>';
          return;
        }
        document.getElementById('cmd-activity').innerHTML = acts.slice(0, 10).map(function(a){
          var t = a.ts ? new Date(a.ts).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }) : '';
          var actor = (a.actor || '').replace('tos-proxy/', '');
          return '<div class="act-row"><div style="color:#cbd5e1;">' + escapeHtml((a.intent||'').slice(0, 110)) + '</div><div style="font-size:10px;color:#64748b;margin-top:2px;">' + actor + ' \xB7 ' + t + '</div></div>';
        }).join('');
      }

      function renderTopRisk() {
        var txns = cmd_data.transactions || [];
        var reds = txns.filter(function(t){ return !t.terminal && t.riskBand === 'RED'; });
        reds.sort(function(a, b){ return (a.closingDate || '9999').localeCompare(b.closingDate || '9999'); });
        var top5 = reds.slice(0, 5);
        var el = document.getElementById('cmd-top-risk');
        if (!el) return;
        if (top5.length === 0) {
          el.innerHTML = '<div style="padding:30px 14px;text-align:center;color:#22c55e;font-size:13px;"><div style="font-size:32px;margin-bottom:6px;">\u2713</div>No deals in RED right now. Nice work.</div>';
          return;
        }
        el.innerHTML = top5.map(function(t) {
          var closing = t.closingDate ? new Date(t.closingDate) : null;
          var daysOut = closing ? Math.floor((closing - new Date()) / 86400000) : null;
          var daysText = daysOut === null ? 'no closing date' : (daysOut < 0 ? Math.abs(daysOut) + 'd overdue' : daysOut + 'd to close');
          var daysColor = daysOut === null ? '#94a3b8' : (daysOut < 0 ? '#ef4444' : daysOut < 7 ? '#f59e0b' : '#cbd5e1');
          var factors = (t.topFactors || '').split(',').slice(0, 3).map(function(s){return s.trim();}).filter(Boolean);
          return '<a href="/tos/dashboard/deal?id=' + encodeURIComponent(t.id) + '" style="display:flex;align-items:center;gap:12px;padding:10px 12px;background:#0f172a;border:1px solid #ef4444;border-radius:8px;margin-bottom:6px;text-decoration:none;cursor:pointer;">' +
            '<div style="flex:1;min-width:0;"><div style="font-size:13px;color:#e2e8f0;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(t.name) + '</div>' +
            '<div style="font-size:10px;color:#94a3b8;margin-top:2px;">Score ' + (t.riskScore != null ? t.riskScore : '?') + (factors.length ? ' \xB7 ' + escapeHtml(factors.join(', ')) : '') + '</div></div>' +
            '<div style="text-align:right;"><div style="font-size:11px;color:' + daysColor + ';font-weight:600;">' + daysText + '</div>' +
            (closing ? '<div style="font-size:10px;color:#64748b;">' + closing.toLocaleDateString() + '</div>' : '') + '</div>' +
            '<span class="pill pill-red">RED ' + (t.riskScore != null ? t.riskScore : '') + '</span>' +
          '</a>';
        }).join('');
      }

      async function loadData() {
        try {
          var t1 = fetch(WORKER_ORIGIN + '/tos/admin/transactions', { cache: 'no-store' }).then(function(r){ return r.json(); });
          var t2 = fetch(WORKER_ORIGIN + '/tos/admin/deadlines', { cache: 'no-store' }).then(function(r){ return r.json(); });
          var t3 = fetch(WORKER_ORIGIN + '/tos/admin/stats', { cache: 'no-store' }).then(function(r){ return r.json(); });
          var res = await Promise.all([t1, t2, t3]);
          if (!res[0].ok) throw new Error('transactions fetch failed');
          cmd_data.transactions = res[0].transactions || [];
          cmd_data.deadlines = (res[1].ok ? res[1].deadlines : []) || [];
          cmd_data.stats = res[2].ok ? res[2] : null;
          renderHero(); renderFunnel(); renderAttention(); renderTopRisk(); renderActivity();
        } catch (e) {
          document.getElementById('hero-tiles').innerHTML = '<div style="grid-column:1/-1;padding:40px;text-align:center;color:#ef4444;">Error: ' + escapeHtml(e.message || e) + '</div>';
        }
      }

      updateCmdAuth();

      // Welcome banner \u2014 show on first visit, dismissible
      (function() {
        if (!localStorage.getItem('tos_welcome_dismissed')) {
          document.getElementById('welcome-banner').style.display = 'block';
        }
      })();
      function dismissWelcome() {
        localStorage.setItem('tos_welcome_dismissed', '1');
        document.getElementById('welcome-banner').style.display = 'none';
      }
      window.dismissWelcome = dismissWelcome;
      async function seedDemoData(ev) {
        ev.preventDefault();
        if (!cmd_apiKey) { alert('Unlock with operator password first (auth bar in Quick Actions)'); return; }
        if (!confirm('Create 5 demo transactions? They are named "DEMO \xB7 ..." and can be bulk-deleted later.')) return;
        var r = await fetch(WORKER_ORIGIN + '/tos/admin/seed-demo', {
          method: 'POST',
          headers: { 'Authorization': 'Bearer ' + cmd_apiKey, 'Content-Type': 'application/json' },
          body: '{}',
        });
        var b = await r.json();
        if (b.skipped) alert('\u26A0\uFE0F ' + b.reason);
        else if (b.ok) { alert('\u2713 Created ' + b.created + ' demo transactions. Refreshing...'); loadData(); }
        else alert('\u2717 Failed: ' + JSON.stringify(b).slice(0, 400));
      }
      window.seedDemoData = seedDemoData;
    `
  });
}
__name(renderCommandDashboardHtml, "renderCommandDashboardHtml");
function renderDealsDashboardHtml(_env, url) {
  const { envLabel, envColor, workerOrigin } = envLabelAndColor(url);
  const CONDO_INTEL_BASE = "https://condo-intel-web.pages.dev";
  const GHL_LOC = "SeZr4YCwEZ50IcWqylkQ";
  return dashboardShell({
    title: "\u{1F0CF} Deals \u2014 Cards View",
    envLabel,
    envColor,
    workerOrigin,
    activeNav: "/tos/dashboard/deals",
    body: `
      <div style="margin-bottom:14px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;">
        <div style="color:#94a3b8;font-size:13px;">Every open transaction at a glance. Warnings + alerts called out per card. Notifications fire through GHL native email + SMS (no external tools).</div>
        <div style="display:flex;gap:6px;align-items:center;font-size:12px;color:#94a3b8;">
          <span style="margin-right:4px;">Filter:</span>
          <button class="dfilter active" data-f="all">All</button>
          <button class="dfilter" data-f="warning">\u26A0\uFE0F Warnings</button>
          <button class="dfilter" data-f="red">\u{1F534} RED</button>
          <button class="dfilter" data-f="condo">\u{1F3E2} Condo</button>
        </div>
      </div>

      <!-- Unlock bar for protected actions (same pattern as /tos/admin) -->
      <div id="d-auth-bar" class="stat-tile" style="margin-bottom:14px;padding:12px 14px;">
        <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
          <span style="font-size:12px;color:#94a3b8;">Action buttons (Notify TC / Recompute Risk) require operator password:</span>
          <input type="password" id="d-api-key" placeholder="Operator password" style="flex:1;min-width:200px;padding:6px 10px;background:#0f172a;border:1px solid #334155;border-radius:5px;color:#e2e8f0;font-size:12px;" />
          <button id="d-unlock" class="admin-btn" style="font-size:11px;">Unlock</button>
          <span id="d-auth-status" style="font-size:11px;color:#64748b;">\u{1F512} locked</span>
        </div>
      </div>

      <!-- Bulk action bar \u2014 visible when at least 1 deal selected -->
      <div id="bulk-bar" style="display:none;margin-bottom:14px;padding:10px 14px;background:linear-gradient(90deg,rgba(34,211,238,0.15),rgba(34,211,238,0.05));border:1px solid #22d3ee;border-radius:8px;align-items:center;gap:12px;flex-wrap:wrap;">
        <span style="font-size:13px;color:#22d3ee;font-weight:600;"><span id="bulk-count">0</span> deals selected</span>
        <button onclick="bulkAction('close')" style="padding:6px 14px;background:#16a34a;color:white;border:none;border-radius:5px;font-size:12px;font-weight:600;cursor:pointer;">\u2713 Bulk Close</button>
        <button onclick="bulkAction('archive')" style="padding:6px 14px;background:#64748b;color:white;border:none;border-radius:5px;font-size:12px;font-weight:600;cursor:pointer;">\u{1F4E6} Bulk Archive</button>
        <button onclick="bulkSendReviews()" style="padding:6px 14px;background:linear-gradient(135deg,#fbbf24,#f59e0b);color:#0f172a;border:none;border-radius:5px;font-size:12px;font-weight:600;cursor:pointer;">\u2B50 Bulk Send Reviews</button>
        <button onclick="bulkClear()" style="padding:6px 14px;background:transparent;color:#cbd5e1;border:1px solid #475569;border-radius:5px;font-size:12px;cursor:pointer;margin-left:auto;">Clear</button>
      </div>

      <div id="deals-grid" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(360px,1fr));gap:14px;">
        <div style="grid-column:1/-1;padding:40px;text-align:center;color:#64748b;">Loading deals\u2026</div>
      </div>

      <style>
        .dfilter { padding: 4px 9px; background: transparent; border: 1px solid #334155; color: #94a3b8; border-radius: 5px; cursor: pointer; font-size: 12px; }
        .dfilter.active, .dfilter:hover { background: #1e3a5f; color: #22d3ee; border-color: #22d3ee; }
        .deal-card { background: #1e293b; border: 1px solid #334155; border-radius: 10px; padding: 18px; display: flex; flex-direction: column; gap: 10px; transition: border-color 0.15s, transform 0.1s; }
        .deal-card:hover { border-color: #22d3ee; transform: translateY(-1px); }
        .deal-card.red-border { border-color: #ef4444; border-width: 2px; }
        .deal-card.yellow-border { border-color: #f59e0b; }
        .deal-name { font-size: 14px; font-weight: 600; color: #e2e8f0; line-height: 1.3; }
        .deal-meta-row { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; font-size: 11px; color: #94a3b8; }
        .chip { display: inline-block; padding: 3px 9px; border-radius: 999px; font-size: 11px; font-weight: 600; }
        .chip-RED { background: rgba(239,68,68,0.18); color: #fca5a5; }
        .chip-YELLOW { background: rgba(245,158,11,0.18); color: #fcd34d; }
        .chip-GREEN { background: rgba(34,197,94,0.18); color: #86efac; }
        .chip-GRAY { background: rgba(100,116,139,0.18); color: #cbd5e1; }
        .chip-condo { background: rgba(168,85,247,0.18); color: #d8b4fe; }
        .warn-row { display: flex; gap: 6px; align-items: flex-start; padding: 6px 8px; background: rgba(239,68,68,0.08); border-left: 2px solid #ef4444; border-radius: 4px; font-size: 12px; color: #fca5a5; }
        .warn-row.yellow { background: rgba(245,158,11,0.08); border-color: #f59e0b; color: #fcd34d; }
        .warn-row.info { background: rgba(34,211,238,0.08); border-color: #22d3ee; color: #7dd3fc; }
        .card-actions { display: flex; gap: 6px; flex-wrap: wrap; padding-top: 8px; border-top: 1px solid #2a3a52; }
        .card-actions a, .card-actions button { padding: 5px 10px; font-size: 11px; background: #1a2236; border: 1px solid #334155; color: #cbd5e1; border-radius: 5px; cursor: pointer; text-decoration: none; transition: border-color 0.15s, color 0.15s; }
        .card-actions a:hover, .card-actions button:hover { border-color: #22d3ee; color: #22d3ee; }
        .card-actions button.primary { background: #14532d; color: #86efac; border-color: #15803d; }
        .card-actions button.primary:hover { background: #166534; color: #4ade80; border-color: #22c55e; }
        .card-actions button:disabled { opacity: 0.5; cursor: not-allowed; }
        .condo-section { padding: 8px 10px; background: rgba(168,85,247,0.06); border-left: 2px solid #a855f7; border-radius: 4px; font-size: 11px; color: #d8b4fe; }
        body[data-theme="light"] .deal-card { background: #ffffff !important; border-color: #e2e8f0 !important; }
        body[data-theme="light"] .deal-name { color: #0f172a !important; }
      </style>
    `,
    bodyScript: `
      var d_data = { transactions: [], deadlines: [] };
      var d_filter = 'all';
      var d_apiKey = localStorage.getItem('tos_admin_key') || '';
      var CONDO_INTEL_BASE = '${CONDO_INTEL_BASE}';
      var GHL_LOC = '${GHL_LOC}';

      function updateDAuth() {
        var unlocked = !!d_apiKey;
        document.getElementById('d-auth-status').innerHTML = unlocked ? '<span style="color:#22c55e">\u{1F513} unlocked</span>' : '<span style="color:#64748b">\u{1F512} locked</span>';
        document.getElementById('d-api-key').style.display = unlocked ? 'none' : 'inline-block';
        document.getElementById('d-unlock').style.display = unlocked ? 'none' : 'inline-block';
        Array.from(document.querySelectorAll('.deal-card button[data-needs-auth]')).forEach(function(b){ b.disabled = !unlocked; });
      }

      document.getElementById('d-unlock').addEventListener('click', function() {
        var k = document.getElementById('d-api-key').value.trim();
        if (!k) { alert('Enter operator password first'); return; }
        d_apiKey = k;
        localStorage.setItem('tos_admin_key', k);
        updateDAuth();
      });

      // Compute warnings client-side from transaction + linked deadlines.
      function warningsFor(t, allDeadlines) {
        var warnings = [];
        var today = new Date(); today.setHours(0,0,0,0);

        if (t.riskBand === 'RED') warnings.push({ level: 'red', icon: '\u{1F534}', text: 'RED risk band \u2014 top factors: ' + (t.riskTopFactors || 'n/a') });
        if (t.closingDate) {
          var due = new Date(t.closingDate); due.setHours(0,0,0,0);
          var days = Math.round((due.getTime() - today.getTime()) / 86400000);
          if (days < 0) warnings.push({ level: 'red', icon: '\u23F0', text: 'Closing was ' + Math.abs(days) + ' days ago \u2014 overdue' });
          else if (days === 0) warnings.push({ level: 'red', icon: '\u{1F3E0}', text: 'Closing TODAY' });
          else if (days <= 7) warnings.push({ level: 'yellow', icon: '\u{1F3E0}', text: 'Closing in ' + days + ' days' });
        } else if (t.stage === 'Contract Intake') {
          warnings.push({ level: 'yellow', icon: '\u{1F4C4}', text: 'No closing date yet \u2014 contract may not be parsed' });
        }
        if (t.riskScore == null && t.stage !== 'Contract Intake') {
          warnings.push({ level: 'info', icon: '\u{1F3AF}', text: 'Risk has not been scored \u2014 click Recompute Risk' });
        }
        // Check linked deadlines (we don't have per-txn links via API, so flag generally if many overdue exist)
        // For now: cards don't show per-txn deadline links; that's a future enhancement.
        return warnings;
      }

      function bandChip(band) {
        var b = band || 'GRAY';
        var label = band || 'UNSCORED';
        return '<span class="chip chip-' + b + '">' + label + '</span>';
      }

      // \u2500\u2500\u2500 Bulk selection state + actions \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
      var bulkSelected = new Set();
      function bulkToggle(id, on) {
        if (on) bulkSelected.add(id); else bulkSelected.delete(id);
        bulkUpdateBar();
      }
      window.bulkToggle = bulkToggle;
      function bulkUpdateBar() {
        var bar = document.getElementById('bulk-bar');
        document.getElementById('bulk-count').textContent = bulkSelected.size;
        bar.style.display = bulkSelected.size > 0 ? 'flex' : 'none';
      }
      function bulkClear() {
        bulkSelected.clear();
        document.querySelectorAll('.deal-card input[type=checkbox]').forEach(function(cb){ cb.checked = false; });
        bulkUpdateBar();
      }
      window.bulkClear = bulkClear;
      async function bulkAction(op) {
        if (!d_apiKey) { alert('Unlock first'); return; }
        if (bulkSelected.size === 0) return;
        var ids = Array.from(bulkSelected);
        var label = op === 'close' ? 'CLOSE' : 'ARCHIVE';
        if (!confirm(label + ' ' + ids.length + ' deals?\\n\\nThis sets stage = ' + (op === 'close' ? 'closed' : 'archived') + ' on each. Audit log entries written. Cannot bulk-undo.')) return;
        var endpoint = op === 'close' ? '/tos/admin/bulk-close' : '/tos/admin/bulk-archive';
        try {
          var r = await fetch(WORKER_ORIGIN + endpoint, {
            method: 'POST',
            headers: { 'Authorization': 'Bearer ' + d_apiKey, 'Content-Type': 'application/json' },
            body: JSON.stringify({ ids: ids })
          });
          var b = await r.json();
          if (!b.ok) { alert('\u2717 ' + (b.error || JSON.stringify(b).slice(0,200))); return; }
          var msg = '\u2713 Bulk ' + op + ' complete\\n\\n' +
            b.summary.ok + ' ok \xB7 ' + b.summary.failed + ' failed';
          if (b.summary.failed > 0) {
            b.results.filter(function(r) { return !r.ok; }).forEach(function(r) {
              msg += '\\n  \u2717 ' + r.id + ': ' + r.error;
            });
          }
          alert(msg);
          bulkClear();
          loadData();
        } catch (e) {
          alert('\u2717 ' + String(e));
        }
      }
      window.bulkAction = bulkAction;

      async function bulkSendReviews() {
        if (!d_apiKey) { alert('Unlock first'); return; }
        if (bulkSelected.size === 0) return;
        var ids = Array.from(bulkSelected);
        if (!confirm('\u2B50 Fire review requests across ALL parties on ' + ids.length + ' selected deals?\\n\\nUses /tos/admin/review-request (cooldown auto-applies per party).\\n\\nClick OK to fire.')) return;
        var totals = { sent: 0, skipped: 0, failed: 0, cooledDown: 0 };
        var deals = [];
        for (var i = 0; i < ids.length; i++) {
          try {
            var r = await fetch(WORKER_ORIGIN + '/tos/admin/review-request', {
              method: 'POST',
              headers: { 'Authorization': 'Bearer ' + d_apiKey, 'Content-Type': 'application/json' },
              body: JSON.stringify({ transactionId: ids[i] })
            });
            var b = await r.json();
            if (b.ok && b.summary) {
              totals.sent += b.summary.sent || 0;
              totals.skipped += b.summary.skipped || 0;
              totals.failed += b.summary.failed || 0;
              totals.cooledDown += b.summary.cooledDown || 0;
              deals.push({ id: ids[i], name: b.transactionName || ids[i], ...b.summary });
            } else {
              totals.failed++;
              deals.push({ id: ids[i], name: '(failed)', sent: 0, skipped: 0, failed: 1 });
            }
          } catch (e) {
            totals.failed++;
            deals.push({ id: ids[i], name: '(error)', error: String(e) });
          }
        }
        var msg = '\u2B50 BULK REVIEW REQUESTS \u2014 ' + ids.length + ' deals\\n\\n' +
          'Totals: ' + totals.sent + ' sent \xB7 ' + totals.skipped + ' skipped (' + totals.cooledDown + ' in cooldown) \xB7 ' + totals.failed + ' failed\\n\\n';
        deals.forEach(function(d) {
          msg += '\u2022 ' + d.name + ': ' + (d.sent || 0) + 's/' + (d.skipped || 0) + 'k/' + (d.failed || 0) + 'f\\n';
        });
        alert(msg);
        bulkClear();
      }
      window.bulkSendReviews = bulkSendReviews;

      function renderCards() {
        var open = d_data.transactions.filter(function(t){ return !t.terminal; });
        var filtered = open.filter(function(t) {
          if (d_filter === 'all') return true;
          if (d_filter === 'red') return t.riskBand === 'RED';
          if (d_filter === 'condo') return t.isCondo === true || (t.name||'').toLowerCase().includes('condo');
          if (d_filter === 'warning') {
            // Has any warning
            return warningsFor(t, d_data.deadlines).length > 0;
          }
          return true;
        });

        if (filtered.length === 0) {
          var emptyMsg = d_data.transactions.length === 0
            ? '<div style="grid-column:1/-1;padding:60px 20px;text-align:center;">' +
                '<div style="font-size:48px;margin-bottom:14px;opacity:0.5;">\u{1F0CF}</div>' +
                '<div style="font-size:16px;color:#cbd5e1;font-weight:600;margin-bottom:8px;">No deals yet</div>' +
                '<div style="font-size:13px;color:#94a3b8;margin-bottom:18px;">Get started by creating your first transaction.</div>' +
                '<div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap;">' +
                  '<a href="/tos/admin" class="admin-btn" style="background:#22c55e;color:#0f172a;text-decoration:none;border:none;">\u{1F4DD} Create transaction \u2192</a>' +
                  '<a href="/tos/intake" target="_blank" class="admin-btn" style="text-decoration:none;">\u{1F4E8} Open public intake form \u2197</a>' +
                  '<a href="#" onclick="(async function(){if(!d_apiKey){alert(\\'Unlock first\\');return;}var r=await fetch(WORKER_ORIGIN+\\'/tos/admin/seed-demo\\',{method:\\'POST\\',headers:{Authorization:\\'Bearer \\'+d_apiKey,\\'Content-Type\\':\\'application/json\\'},body:\\'{}\\'});var b=await r.json();alert(b.skipped?b.reason:\\'\u2713 Created \\'+b.created+\\' demo deals \u2014 refreshing\\');loadData();})();return false;" class="admin-btn" style="text-decoration:none;">\u{1F331} Seed 5 demo deals</a>' +
                '</div>' +
              '</div>'
            : '<div style="grid-column:1/-1;padding:40px;text-align:center;color:#64748b;">No deals match the <strong>' + d_filter + '</strong> filter. Try All.</div>';
          document.getElementById('deals-grid').innerHTML = emptyMsg;
          return;
        }

        // Sort: RED first, then YELLOW, then by closing date ascending
        filtered.sort(function(a,b){
          var ra = a.riskBand === 'RED' ? 0 : a.riskBand === 'YELLOW' ? 1 : 2;
          var rb = b.riskBand === 'RED' ? 0 : b.riskBand === 'YELLOW' ? 1 : 2;
          if (ra !== rb) return ra - rb;
          return (a.closingDate || '9999').localeCompare(b.closingDate || '9999');
        });

        var html = filtered.map(function(t) {
          var warnings = warningsFor(t, d_data.deadlines);
          var borderClass = t.riskBand === 'RED' ? 'red-border' : (warnings.some(function(w){return w.level==='red';}) ? 'red-border' : (warnings.some(function(w){return w.level==='yellow';}) ? 'yellow-border' : ''));
          var ghlLink = 'https://app.gohighlevel.com/v2/location/' + GHL_LOC + '/contacts/smart_list/All';  // GHL Custom Object record direct link convention varies; safest is contacts list
          var condoLink = CONDO_INTEL_BASE;

          var warnsHtml = warnings.length === 0
            ? '<div style="font-size:11px;color:#64748b;">No active warnings.</div>'
            : warnings.map(function(w){
                return '<div class="warn-row ' + w.level + '">' + w.icon + ' <span>' + escapeHtml(w.text) + '</span></div>';
              }).join('');

          var condoHtml = t.isCondo === true ? (
            '<div class="condo-section">' +
              '\u{1F3E2} <strong>Condo Intel add-on</strong> \xB7 isCondo flag set on this transaction. ' +
              '<a href="' + condoLink + '" target="_blank" style="color:#d8b4fe;text-decoration:underline;">Open Condo Intel \u2197</a>' +
              '<div style="font-size:10px;color:#a78bfa;margin-top:3px;">Future: pull HOA name + approval status here from condo_transaction custom object.</div>' +
            '</div>'
          ) : '';

          var detailHref = '/tos/dashboard/deal?id=' + encodeURIComponent(t.id);
          var checked = bulkSelected.has(t.id) ? 'checked' : '';
          return '<div class="deal-card ' + borderClass + '" data-id="' + t.id + '" onclick="if(event.target.tagName !== \\'BUTTON\\' && event.target.tagName !== \\'A\\' && event.target.tagName !== \\'INPUT\\') location.href=\\'' + detailHref + '\\'" style="cursor:pointer;">' +
            '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;">' +
              '<label style="display:flex;align-items:center;gap:6px;cursor:pointer;" onclick="event.stopPropagation();"><input type="checkbox" ' + checked + ' onchange="bulkToggle(\\''+t.id+'\\', this.checked)" style="cursor:pointer;margin:0;" /><span style="font-size:10px;color:#64748b;">select</span></label>' +
              '<div class="deal-name" style="flex:1;">' + escapeHtml(t.name) + '</div>' +
              bandChip(t.riskBand) +
            '</div>' +
            '<div class="deal-meta-row">' +
              '<span>\u{1F4CD} ' + escapeHtml(t.stage) + '</span>' +
              '<span>\xB7</span>' +
              '<span>' + escapeHtml(t.side || 'Side?') + '</span>' +
              (t.closingDate ? '<span>\xB7</span><span>\u{1F5D3} ' + fmtDate(t.closingDate) + '</span>' : '<span>\xB7</span><span style="color:#64748b">no closing date</span>') +
              (t.isCondo === true ? '<span>\xB7</span><span class="chip chip-condo">\u{1F3E2} Condo</span>' : '') +
            '</div>' +
            // \u2500\u2500 Next deadline (computed from d_data.deadlines linked to this txn) \u2500\u2500
            (function(){
              var today = new Date(); today.setHours(0,0,0,0);
              var todayStr = today.toISOString().slice(0,10);
              var mine = (d_data.deadlines || []).filter(function(d){
                return d.parentTransactionId === t.id && d.dueDate && d.dueDate >= todayStr && (d.status||'').toLowerCase() !== 'complete' && (d.status||'').toLowerCase() !== 'completed';
              });
              if (mine.length === 0) return '';
              mine.sort(function(a,b){ return a.dueDate.localeCompare(b.dueDate); });
              var next = mine[0];
              var dayLabel = next.daysUntil === 0 ? 'TODAY' : (next.daysUntil === 1 ? 'tomorrow' : 'in ' + next.daysUntil + 'd');
              var color = next.daysUntil <= 2 ? '#fca5a5' : (next.daysUntil <= 7 ? '#fcd34d' : '#86efac');
              return '<div style="margin:6px 0 4px 0;padding:6px 10px;background:rgba(245,158,11,0.10);border-left:3px solid ' + color + ';border-radius:4px;font-size:11px;color:' + color + ';">' +
                '\u23F0 <strong>Next:</strong> ' + escapeHtml(next.type) + ' \u2014 ' + fmtDate(next.dueDate) + ' (' + dayLabel + ')' +
              '</div>';
            })() +
            // \u2500\u2500 Quick stats row (parties \xB7 docs \xB7 deadlines \xB7 days at stage \xB7 parser) \u2500\u2500
            '<div class="deal-stats-row" style="display:flex;flex-wrap:wrap;gap:6px;margin:6px 0 4px 0;font-size:11px;">' +
              '<span title="Linked parties" style="background:rgba(59,130,246,0.18);color:#93c5fd;padding:2px 7px;border-radius:10px;">\u{1F465} ' + (t.partyCount || 0) + ' ' + ((t.partyCount === 1) ? 'party' : 'parties') + '</span>' +
              '<span title="Attached contract/document packets" style="background:rgba(168,85,247,0.18);color:#d8b4fe;padding:2px 7px;border-radius:10px;">\u{1F4CE} ' + (t.documentCount || 0) + ' doc' + ((t.documentCount === 1) ? '' : 's') + '</span>' +
              '<span title="Linked deadlines" style="background:rgba(245,158,11,0.18);color:#fcd34d;padding:2px 7px;border-radius:10px;">\u23F0 ' + (t.deadlineCount || 0) + ' deadline' + ((t.deadlineCount === 1) ? '' : 's') + '</span>' +
              (t.daysAtStage !== null && t.daysAtStage !== undefined ? '<span title="Days since contract effective date" style="background:rgba(100,116,139,0.18);color:#cbd5e1;padding:2px 7px;border-radius:10px;">\u23F1 ' + t.daysAtStage + 'd active</span>' : '') +
              (function(){
                var ps = (t.parserStatus || 'pending').toLowerCase();
                var bg = ps === 'success' ? 'rgba(34,197,94,0.18)' : (ps === 'failed' ? 'rgba(239,68,68,0.18)' : 'rgba(100,116,139,0.18)');
                var fg = ps === 'success' ? '#86efac' : (ps === 'failed' ? '#fca5a5' : '#94a3b8');
                var ic = ps === 'success' ? '\u2705' : (ps === 'failed' ? '\u26A0\uFE0F' : '\u23F3');
                var conf = (t.parserConfidence != null) ? ' ' + Math.round(t.parserConfidence * 100) + '%' : '';
                return '<span title="Parser status' + (conf ? ' (confidence' + conf + ')' : '') + '" style="background:' + bg + ';color:' + fg + ';padding:2px 7px;border-radius:10px;">' + ic + ' parser: ' + ps + conf + '</span>';
              })() +
            '</div>' +
            '<div style="display:flex;flex-direction:column;gap:5px;">' + warnsHtml + '</div>' +
            condoHtml +
            '<div class="card-actions">' +
              '<a href="' + detailHref + '" style="background:#0c4a6e;color:#7dd3fc;border-color:#0369a1;">\u{1F50D} Open Details</a>' +
              '<a href="' + ghlLink + '" target="_blank">View in GHL \u2197</a>' +
              '<button data-needs-auth onclick="event.stopPropagation();recomputeRiskFor(\\'' + t.id + '\\')">Recompute Risk</button>' +
              '<button data-needs-auth onclick="event.stopPropagation();reparseFor(\\'' + t.id + '\\')" title="Re-run OCR + extract on attached contract">\u{1F501} Re-parse</button>' +
              '<button data-needs-auth onclick="event.stopPropagation();mergeFromCard(\\'' + t.id + '\\', \\'' + escapeHtml(t.name).replace(/\\'/g,"\\\\'") + '\\')" title="Merge this deal into another (for duplicates)">\u{1F500} Merge</button>' +
              '<button data-needs-auth class="primary" onclick="event.stopPropagation();notifyFor(\\'' + t.id + '\\', \\'' + escapeHtml(t.name).replace(/\\'/g,"\\\\'") + '\\')">\u{1F4E7} Notify TC</button>' +
              '<div class="mono" style="margin-left:auto;font-size:10px;color:#64748b;align-self:center;">' + t.id.slice(0,10) + '\u2026</div>' +
            '</div>' +
          '</div>';
        }).join('');

        document.getElementById('deals-grid').innerHTML = html;
        updateDAuth();
      }

      async function recomputeRiskFor(txnId) {
        if (!d_apiKey) { alert('Unlock first'); return; }
        var r = await fetch(WORKER_ORIGIN + '/tos/risk/recompute', {
          method: 'POST',
          headers: { 'Authorization': 'Bearer ' + d_apiKey, 'Content-Type': 'application/json' },
          body: JSON.stringify({ transactionId: txnId }),
        });
        var body = await r.json();
        alert('Risk recompute: HTTP ' + r.status + '\\n\\n' + JSON.stringify(body, null, 2).slice(0, 600));
        loadData();
      }
      window.recomputeRiskFor = recomputeRiskFor;

      async function reparseFor(txnId) {
        if (!d_apiKey) { alert('Unlock first'); return; }
        if (!confirm('Re-run OCR + extract on the contract attached to this deal?\\n\\nThis pulls the stored PDF, OCRs it, asks Claude to extract fields, and writes results back to the deal.')) return;
        var r = await fetch(WORKER_ORIGIN + '/tos/admin/transaction/' + encodeURIComponent(txnId) + '/reparse', {
          method: 'POST',
          headers: { 'Authorization': 'Bearer ' + d_apiKey, 'Content-Type': 'application/json' },
          body: '{}',
        });
        var body = await r.json();
        if (!body.ok) {
          alert('Re-parse failed:\\n\\n' + (body.error || JSON.stringify(body).slice(0, 600)));
          return;
        }
        var summary = 'Re-parse complete.\\n\\nPackets found: ' + body.packetsFound + '\\nResults:\\n';
        (body.results || []).forEach(function(r){
          summary += '  \u2022 ' + r.packetId.slice(0, 8) + ': ' + (r.ok ? '\u2713 parsed' : (r.skipped ? '\u2298 skipped \u2014 ' + (r.reason||'') : '\u2717 failed \u2014 ' + (r.reason||'')));
          if (r.parser && r.parser.skipped) summary += ' (parser: ' + (r.parser.reason || 'skipped') + ')';
          if (r.parser && typeof r.parser.confidence === 'number') summary += ' conf=' + Math.round(r.parser.confidence * 100) + '%';
          summary += '\\n';
        });
        alert(summary);
        loadData();
      }
      window.reparseFor = reparseFor;

      async function mergeFromCard(sourceId, sourceName) {
        if (!d_apiKey) { alert('Unlock first'); return; }
        // Show a list of OTHER open deals to merge INTO
        var candidates = (d_data.transactions || []).filter(function(t){ return t.id !== sourceId && !t.terminal; });
        if (candidates.length === 0) { alert('No other open deals to merge into.'); return; }
        var options = candidates.map(function(t, i){ return (i+1) + '. ' + t.name + '  (' + t.id.slice(0,8) + ')'; }).join('\\n');
        var pick = prompt('Merge "' + sourceName + '" INTO which deal?\\n\\n' + options + '\\n\\nEnter the number (1-' + candidates.length + ') of the TARGET deal that will keep all the parties/docs/deadlines:');
        if (!pick) return;
        var idx = parseInt(pick, 10) - 1;
        if (isNaN(idx) || idx < 0 || idx >= candidates.length) { alert('Invalid pick.'); return; }
        var target = candidates[idx];
        // Dry-run first
        var dr = await fetch(WORKER_ORIGIN + '/tos/admin/transactions/merge', {
          method: 'POST',
          headers: { 'Authorization': 'Bearer ' + d_apiKey, 'Content-Type': 'application/json' },
          body: JSON.stringify({ sourceId: sourceId, targetId: target.id, dryRun: true }),
        });
        var drBody = await dr.json();
        if (!drBody.ok) { alert('Dry-run failed:\\n' + JSON.stringify(drBody).slice(0,600)); return; }
        var wm = drBody.wouldMove || {};
        var confirmMsg = 'CONFIRM MERGE\\n\\n' +
          'FROM:  ' + sourceName + '  (will be renamed [MERGED \u2192] + moved to Closed-Lost)\\n' +
          'INTO:  ' + target.name + '  (keeps everything + gets source items)\\n\\n' +
          'Will move:\\n' +
          '  \u2022 ' + (wm.parties || 0) + ' parties\\n' +
          '  \u2022 ' + (wm.deadlines || 0) + ' deadlines\\n' +
          '  \u2022 ' + (wm.documents || 0) + ' documents\\n\\n' +
          'Proceed?';
        if (!confirm(confirmMsg)) return;
        var r = await fetch(WORKER_ORIGIN + '/tos/admin/transactions/merge', {
          method: 'POST',
          headers: { 'Authorization': 'Bearer ' + d_apiKey, 'Content-Type': 'application/json' },
          body: JSON.stringify({ sourceId: sourceId, targetId: target.id }),
        });
        var body = await r.json();
        if (!body.ok) { alert('Merge failed:\\n' + JSON.stringify(body).slice(0,600)); return; }
        alert('\u2713 Merge complete.\\n\\n' + (body.summary || '') + '\\n\\nReloading\u2026');
        loadData();
      }
      window.mergeFromCard = mergeFromCard;

      async function notifyFor(txnId, name) {
        if (!d_apiKey) { alert('Unlock first'); return; }
        if (!confirm('Send GHL notification (email + SMS) about: ' + name + '?')) return;
        var r = await fetch(WORKER_ORIGIN + '/tos/admin/notify', {
          method: 'POST',
          headers: { 'Authorization': 'Bearer ' + d_apiKey, 'Content-Type': 'application/json' },
          body: JSON.stringify({ transactionId: txnId, severity: 'alert', message: 'Manual notify: ' + name }),
        });
        var body = await r.json();
        if (body.skipped) {
          alert('\u26A0\uFE0F Notify endpoint is configured but TOS_NOTIFY_GHL_WEBHOOK_URL is not set. See docs/runbooks/NOTIFY-SETUP.md to wire it.\\n\\n' + (body.reason || ''));
        } else if (body.ok) {
          alert('\u2713 Notification sent to GHL workflow (status ' + body.ghlResponseStatus + ').\\n\\nGHL will fire email + SMS per your workflow setup.');
        } else {
          alert('\u2717 Notify failed:\\n\\n' + JSON.stringify(body, null, 2).slice(0, 600));
        }
      }
      window.notifyFor = notifyFor;

      Array.from(document.querySelectorAll('.dfilter')).forEach(function(b){
        b.addEventListener('click', function() {
          document.querySelectorAll('.dfilter').forEach(function(x){ x.classList.remove('active'); });
          b.classList.add('active');
          d_filter = b.getAttribute('data-f');
          renderCards();
        });
      });

      async function loadData() {
        try {
          var t1 = fetch(WORKER_ORIGIN + '/tos/admin/transactions', { cache: 'no-store' }).then(function(r){ return r.json(); });
          var t2 = fetch(WORKER_ORIGIN + '/tos/admin/deadlines', { cache: 'no-store' }).then(function(r){ return r.json(); });
          var res = await Promise.all([t1, t2]);
          if (!res[0].ok || !res[1].ok) throw new Error('fetch failed');
          d_data.transactions = res[0].transactions || [];
          d_data.deadlines = res[1].deadlines || [];
          renderCards();
        } catch (e) {
          document.getElementById('deals-grid').innerHTML = '<div style="grid-column:1/-1;padding:40px;text-align:center;color:#ef4444;">Error: ' + escapeHtml(e.message || e) + '</div>';
        }
      }

      updateDAuth();
    `
  });
}
